99	function setAboutHeroSloganSurfaceAlpha(progress: number): void {
100	  const element = getAboutHeroSloganElement();
101	  if (!element) return;
102	  const clampedProgress = Math.max(0, Math.min(1, progress));
103	  const alpha =
